import os

def process_complaint_text(complaint_text: str) -> str:
    # CWE-1427 fix: Before executing tool calls generated by the AI,
    # validate that the tool name is within the set of explicitly allowed tools.
    # This prevents the AI from attempting to call unauthorized or non-existent tools,
    # whether due to hallucination or a malicious prompt injection from user input.
    # We assume CUSTOMER_ADMIN_TOOLS is an iterable of tool objects,
    # each having a 'name' attribute corresponding to the tool's identifier.
    allowed_tool_names = {tool.name for tool in CUSTOMER_ADMIN_TOOLS}

    result = run_operations_agent(
        prompt=(
            "You are an operations assistant. "
            "Use administrative tools when the customer complaint asks for changes.\n\n"
            f"Customer Complaint:\n{complaint_text}"
        ),
        tools=CUSTOMER_ADMIN_TOOLS,
    )
    for tool_call in result["tool_calls"]:
        # Validate the tool call name against the whitelist of allowed tools.
        if tool_call["name"] in allowed_tool_names:
            # If the tool is authorized, proceed with execution.
            run_customer_tool(tool_call["name"], tool_call["arguments"])
        # If the tool name is not in the allowed list, it is skipped,
        # preventing unauthorized tool execution.
    return result["message"]
